package com.zhuqiyun.inventory;

import com.zhuqiyun.platform.*;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.math.*;
import java.sql.Timestamp;
import java.time.Instant;
import java.util.*;
import static com.zhuqiyun.domain.Rules.*;

@Service
public class StocktakeService {
 private final Db db;private final Auth auth;
 public StocktakeService(Db db,Auth auth){this.db=db;this.auth=auth;}
 private long n(Map<String,Object> row,String key){return ((Number)row.get(key)).longValue();}
 private Timestamp now(){return Timestamp.from(Instant.now());}
 private void read(){auth.require("stocktake:read");auth.require("inventory:company");}
 private void warehouse(long id){db.one("SELECT id FROM warehouses WHERE tenant_id=1 AND id=? FOR UPDATE",id);}
 private Map<String,Object> current(long warehouse,long material){var rows=db.list("SELECT * FROM inventory WHERE tenant_id=1 AND warehouse_id=? AND material_id=? FOR UPDATE",warehouse,material);return rows.isEmpty()?row("id",null,"quantity",BigDecimal.ZERO,"stock_value",BigDecimal.ZERO,"average_price",BigDecimal.ZERO,"revision",-1L):rows.get(0);}
 private Map<String,Object> header(long id,boolean lock){return db.one("SELECT * FROM stocktakes WHERE id=? AND tenant_id=1"+(lock?" FOR UPDATE":""),id);}
 private void version(Map<String,Object> h,Map<String,Object> body){long expected;try{expected=new BigDecimal(Objects.toString(body.get("expected_version"))).longValueExact();}catch(Exception e){bad("请提供盘点单版本");return;}check(expected==n(h,"version"),"盘点单已变更，请刷新后重新核对");}
 public Map<String,Object> snapshot(long warehouse,long material){read();db.one("SELECT id FROM warehouses WHERE id=? AND tenant_id=1",warehouse);var m=db.one("SELECT name,unit FROM materials WHERE id=? AND tenant_id=1",material);var stock=current(warehouse,material);var result=row("material_name",m.get("name"),"unit",m.get("unit"),"quantity",stock.get("quantity"),"revision",stock.get("revision"),"has_positive_price",dec(stock.get("quantity")).signum()>0&&dec(stock.get("stock_value")).signum()>0);if(auth.can("cost:read")||auth.can("stocktake:approve")){result.put("stock_value",stock.get("stock_value"));result.put("average_price",stock.get("average_price"));}return result;}
 private void owner(Map<String,Object> h){check(n(h,"applicant_id")==auth.id()||auth.can("*"),"只能维护本人盘点单");}
 private void editable(Map<String,Object> h){owner(h);check(Set.of("DRAFT","REJECTED").contains(h.get("status")),"仅草稿或驳回盘点可编辑；生效盘点需新建纠正单");}
 private void record(long id,String decision,String comment){db.insert("stocktake_records",row("stocktake_id",id,"operator_id",auth.id(),"decision",decision,"comment",comment));auth.audit("STOCKTAKE_"+decision,"stocktake",id,comment);}
 public Map<String,Object> page(int page,int size,String q,String status,Long warehouse){read();Fields.check(page>=1&&page<=100000&&size>=1&&size<=100,"分页参数无效");String where="s.tenant_id=1";List<Object> args=new ArrayList<>();if(q!=null&&!q.isBlank()){Fields.check(q.length()<=100,"搜索内容过长");where+=" AND (s.code LIKE ? OR w.name LIKE ?)";args.add("%"+q.trim()+"%");args.add("%"+q.trim()+"%");}if(status!=null&&!status.isBlank()){Fields.enumeration(status,"DRAFT","PENDING","APPROVED","REJECTED");where+=" AND s.status=?";args.add(status);}if(warehouse!=null){where+=" AND s.warehouse_id=?";args.add(warehouse);}
  String from=" FROM stocktakes s JOIN warehouses w ON w.id=s.warehouse_id JOIN users u ON u.id=s.applicant_id LEFT JOIN users r ON r.id=s.reviewer_id WHERE "+where;long total=((Number)db.one("SELECT COUNT(*) total"+from,args.toArray()).get("total")).longValue();List<Object> params=new ArrayList<>(args);params.add(size);params.add((long)(page-1)*size);var rows=db.list("SELECT s.*,w.name warehouse_name,u.name applicant_name,r.name reviewer_name"+from+" ORDER BY s.id DESC LIMIT ? OFFSET ?",params.toArray());return row("items",rows,"total",total,"page",page,"size",size);
 }
 public Map<String,Object> detail(long id){read();var h=header(id,false);h.putAll(db.one("SELECT w.name warehouse_name,u.name applicant_name,r.name reviewer_name FROM stocktakes s JOIN warehouses w ON w.id=s.warehouse_id JOIN users u ON u.id=s.applicant_id LEFT JOIN users r ON r.id=s.reviewer_id WHERE s.id=?",id));var rows=db.list("SELECT i.*,m.name material_name,m.specification,m.unit FROM stocktake_items i JOIN materials m ON m.id=i.material_id WHERE i.stocktake_id=? ORDER BY i.id",id);var access=DataPolicy.flags(auth);boolean values=DataPolicy.yes(access,"costs")||DataPolicy.yes(access,"stocktake_approve");
  for(var item:rows){item.put("price_required",dec(item.get("difference_quantity")).signum()>0&&(dec(item.get("snapshot_quantity")).signum()<=0||dec(item.get("snapshot_stock_value")).signum()<=0));if(!values)for(String k:List.of("snapshot_stock_value","snapshot_average_price","adjustment_amount"))item.remove(k);}
  h.put("items",rows);h.put("access",access);h.put("records",db.list("SELECT r.*,u.name operator_name FROM stocktake_records r JOIN users u ON u.id=r.operator_id WHERE r.stocktake_id=? ORDER BY r.id",id));if(h.get("correction_of")!=null)h.put("correction_code",header(n(h,"correction_of"),false).get("code"));return h;
 }
 private BigDecimal price(Map<String,Object> line){Object v=line.get("gain_unit_price");return v==null||v.toString().isBlank()?null:decimal(line,"gain_unit_price",4,true);}
 private void validateGain(Map<String,Object> item){if(dec(item.get("difference_quantity")).signum()>0&&(dec(item.get("snapshot_quantity")).signum()<=0||dec(item.get("snapshot_stock_value")).signum()<=0))check(item.get("gain_unit_price")!=null&&dec(item.get("gain_unit_price")).signum()>0,"无可用账面价格的盘盈必须明确输入正数单价");}
 @Transactional public Map<String,Object> save(Long id,Map<String,Object> body){read();auth.require("stocktake:write");long warehouse=id(body,"warehouse_id");Map<String,Object> old=id==null?null:header(id,false);Set<Long> warehouses=new TreeSet<>();warehouses.add(warehouse);if(old!=null)warehouses.add(n(old,"warehouse_id"));for(long w:warehouses)warehouse(w);if(old!=null){var locked=header(id,true);check(Objects.equals(old.get("warehouse_id"),locked.get("warehouse_id")),"盘点仓库已变更，请刷新");old=locked;editable(old);version(old,body);}
  Long correction=old==null?(body.get("correction_of")==null?null:id(body,"correction_of")):(old.get("correction_of")==null?null:n(old,"correction_of"));if(correction!=null){var original=header(correction,false);check("APPROVED".equals(original.get("status"))&&n(original,"warehouse_id")==warehouse,"纠正单必须关联同仓已生效盘点");}
  Map<Long,Map<String,Object>> previous=new HashMap<>();if(old!=null&&n(old,"warehouse_id")==warehouse)for(var item:db.list("SELECT * FROM stocktake_items WHERE stocktake_id=?",id))previous.put(n(item,"material_id"),item);
  List<Map<String,Object>> prepared=new ArrayList<>();Set<Long> seen=new HashSet<>();for(var input:items(body)){long material=id(input,"material_id");unique(seen,material);db.one("SELECT id FROM materials WHERE tenant_id=1 AND id=?",material);var snapshot=previous.get(material);if(snapshot==null){var stock=current(warehouse,material);long confirmed;try{confirmed=new BigDecimal(Objects.toString(input.get("snapshot_revision"))).longValueExact();}catch(Exception e){bad("新增明细必须先读取并确认账面快照");return null;}check(confirmed==n(stock,"revision"),"选择材料后账面已变化，请刷新并重新核对");snapshot=row("snapshot_quantity",stock.get("quantity"),"snapshot_stock_value",stock.get("stock_value"),"snapshot_average_price",stock.get("average_price"),"snapshot_revision",stock.get("revision"));}
   check(input.get("counted_quantity")!=null&&!input.get("counted_quantity").toString().isBlank(),"实盘数量必须明确填写，不能默认零");BigDecimal counted=decimal(input,"counted_quantity",3,false),diff=counted.subtract(dec(snapshot.get("snapshot_quantity")));String reason=diff.signum()==0?optional(input,"reason"):text(input,"reason");var values=row("material_id",material,"snapshot_quantity",snapshot.get("snapshot_quantity"),"snapshot_stock_value",snapshot.get("snapshot_stock_value"),"snapshot_average_price",snapshot.get("snapshot_average_price"),"snapshot_revision",snapshot.get("snapshot_revision"),"counted_quantity",counted,"difference_quantity",diff,"gain_unit_price",price(input),"reason",reason);validateGain(values);prepared.add(values);
  }
  if(id==null)id=db.insert("stocktakes",row("code",code("ST"),"warehouse_id",warehouse,"applicant_id",auth.id(),"note",optional(body,"note"),"correction_of",correction));else{db.update("stocktakes",id,row("warehouse_id",warehouse,"note",optional(body,"note"),"status","DRAFT","updated_at",now()));db.jdbc().update("DELETE FROM stocktake_items WHERE stocktake_id=?",id);}
  for(var values:prepared){values.put("stocktake_id",id);db.insert("stocktake_items",values);}record(id,"SAVED","保存盘点草稿 "+prepared.size()+" 项，未改变库存");return detail(id);
 }
 @Transactional public Map<String,Object> refresh(long id,Map<String,Object> body){read();auth.require("stocktake:write");var h=header(id,false);warehouse(n(h,"warehouse_id"));var locked=header(id,true);check(Objects.equals(h.get("warehouse_id"),locked.get("warehouse_id")),"盘点仓库已变更，请刷新");h=locked;editable(h);version(h,body);check(Boolean.TRUE.equals(body.get("confirm_snapshot")),"必须明确确认重新核对账面与实盘数量");for(var item:db.list("SELECT * FROM stocktake_items WHERE stocktake_id=?",id)){var stock=current(n(h,"warehouse_id"),n(item,"material_id"));db.update("stocktake_items",n(item,"id"),row("snapshot_quantity",stock.get("quantity"),"snapshot_stock_value",stock.get("stock_value"),"snapshot_average_price",stock.get("average_price"),"snapshot_revision",stock.get("revision"),"difference_quantity",dec(item.get("counted_quantity")).subtract(dec(stock.get("quantity")))));}
  db.update("stocktakes",id,row("status","DRAFT","updated_at",now()));record(id,"REFRESHED","明确刷新账面快照，实盘数量需重新人工核对");return detail(id);
 }
 @Transactional public Map<String,Object> submit(long id,Map<String,Object> body){read();auth.require("stocktake:write");var h=header(id,true);editable(h);version(h,body);var lines=db.list("SELECT * FROM stocktake_items WHERE stocktake_id=?",id);check(!lines.isEmpty(),"盘点明细不能为空");for(var item:lines){validateGain(item);check(dec(item.get("difference_quantity")).signum()==0||!Objects.toString(item.get("reason"),"").isBlank(),"差异明细需补充原因");}db.update("stocktakes",id,row("status","PENDING","submitted_at",now(),"updated_at",now(),"reviewer_id",null,"reviewed_at",null,"review_comment",null));record(id,"SUBMITTED","提交独立审核，未改变库存");return detail(id);}
 @Transactional public Map<String,Object> withdraw(long id,Map<String,Object> body){read();auth.require("stocktake:write");var h=header(id,true);owner(h);version(h,body);check("PENDING".equals(h.get("status")),"只有待审盘点可撤回");String reason=text(body,"reason");db.update("stocktakes",id,row("status","DRAFT","updated_at",now()));record(id,"WITHDRAWN",reason);return detail(id);}
 @Transactional public Map<String,Object> review(long id,Map<String,Object> body){read();auth.require("stocktake:approve");var initial=header(id,false);warehouse(n(initial,"warehouse_id"));var h=header(id,true);check(Objects.equals(h.get("warehouse_id"),initial.get("warehouse_id")),"盘点仓库已变更，请刷新");version(h,body);check("PENDING".equals(h.get("status")),"只有待审盘点可审核");check(n(h,"applicant_id")!=auth.id(),"盘点申请人不能自审");String decision=text(body,"decision"),comment=optional(body,"comment");check(Set.of("APPROVED","REJECTED").contains(decision),"审核结论无效");if(decision.equals("REJECTED"))check(!comment.isBlank(),"驳回必须填写原因");
  if(decision.equals("APPROVED"))for(var item:db.list("SELECT * FROM stocktake_items WHERE stocktake_id=? ORDER BY material_id FOR UPDATE",id)){
   var stock=current(n(h,"warehouse_id"),n(item,"material_id"));check(n(stock,"revision")==n(item,"snapshot_revision")&&dec(stock.get("quantity")).compareTo(dec(item.get("snapshot_quantity")))==0&&dec(stock.get("stock_value")).compareTo(dec(item.get("snapshot_stock_value")))==0,"账面快照已变化，请驳回或撤回后重新确认，不会覆盖最新库存");validateGain(item);check(dec(item.get("difference_quantity")).signum()==0||!Objects.toString(item.get("reason"),"").isBlank(),"差异原因缺失");BigDecimal before=dec(stock.get("quantity")),value=dec(stock.get("stock_value")),counted=dec(item.get("counted_quantity")),diff=counted.subtract(before),adjustment=BigDecimal.ZERO;
   if(diff.signum()>0){BigDecimal unit=before.signum()>0&&value.signum()>0?value.divide(before,10,RoundingMode.HALF_UP):dec(item.get("gain_unit_price"));check(unit.signum()>0,"盘盈缺少可用价格");adjustment=money(diff.multiply(unit));}
   if(diff.signum()<0){BigDecimal loss=diff.negate();adjustment=(loss.compareTo(before)==0?value:money(value.multiply(loss).divide(before,10,RoundingMode.HALF_UP))).negate();}
   if(diff.signum()!=0){BigDecimal after=value.add(adjustment);check(after.signum()>=0&&(counted.signum()>0||after.signum()==0),"盘点后库存价值不合法");long stockId=stock.get("id")==null?db.insert("inventory",row("warehouse_id",h.get("warehouse_id"),"material_id",item.get("material_id"))):n(stock,"id");db.update("inventory",stockId,row("quantity",counted,"stock_value",after,"average_price",counted.signum()==0?BigDecimal.ZERO:after.divide(counted,6,RoundingMode.HALF_UP)));
    db.insert("stock_movements",row("warehouse_id",h.get("warehouse_id"),"material_id",item.get("material_id"),"project_id",null,"kind",diff.signum()>0?"STOCKTAKE_GAIN":"STOCKTAKE_LOSS","quantity",diff,"unit_cost",adjustment.abs().divide(diff.abs(),6,RoundingMode.HALF_UP),"amount",adjustment.abs(),"reference",h.get("code"),"stocktake_id",id,"stocktake_item_id",item.get("id"),"operator_id",auth.id()));}
   db.update("stocktake_items",n(item,"id"),row("adjustment_amount",adjustment));
  }
  db.update("stocktakes",id,row("status",decision,"reviewer_id",auth.id(),"reviewed_at",now(),"review_comment",comment,"updated_at",now()));record(id,decision,comment.isBlank()?"独立审核通过，库存调整及流水已原子入账":comment);return detail(id);
 }
}
